WITH lines AS (SELECT id, service, host, log_ts, level, latency_ms, status_code, key, value FROM app_logs LATERAL VIEW EXPLODE(context) t AS key, value) SELECT service, COUNT(*) FILTER (WHERE host = 'h2') AS h2_rows, MIN(log_ts) AS started_at, COUNT(*) AS cnt, APPROX_PERCENTILE(latency_ms, 0.95) AS latency_ms_p95, COUNT(CASE WHEN level = 'WARN' THEN 1 END) AS warn_count FROM lines GROUP BY 1 HAVING COUNT(CASE WHEN level = 'WARN' THEN 1 END) < 1000 ORDER BY service NULLS LAST
